    AppBskyNotificationListNotifications: {
        lexicon: 1,
        id: 'app.bsky.notification.listNotifications',
        defs: {
            main: {
                type: 'query',
                description: 'Enumerate notifications for the requesting account. Requires auth.',
                parameters: {
                    type: 'params',
                    properties: {
                        reasons: {
                            description: 'Notification reasons to include in response.',
                            type: 'array',
                            items: {
                                type: 'string',
                                description: 'A reason that matches the reason property of #notification.',
                            },
                        },
                        limit: {
                            type: 'integer',
                            minimum: 1,
                            maximum: 100,
                            default: 50,
                        },
                        priority: {
                            type: 'boolean',
                            description: 'Deprecated: this parameter is ignored.',
                        },
                        cursor: {
                            type: 'string',
                        },
                        seenAt: {
                            type: 'string',
                            format: 'datetime',
                            description: 'Deprecated: this parameter is unsupported and will cause an error.',
                        },
                    },
                },
                output: {
                    encoding: 'application/json',
                    schema: {
                        type: 'object',
                        required: ['notifications'],
                        properties: {
                            cursor: {
                                type: 'string',
                            },
                            notifications: {
                                type: 'array',
                                items: {
                                    type: 'ref',
                                    ref: 'lex:app.bsky.notification.listNotifications#notification',
                                },
                            },
                            priority: {
                                type: 'boolean',
                                description: 'Deprecated: this field is no longer populated.',
                            },
                            seenAt: {
                                type: 'string',
                                format: 'datetime',
                            },
                        },
                    },
                },
            },
            notification: {
                type: 'object',
                required: [
                    'uri',
                    'cid',
                    'author',
                    'reason',
                    'record',
                    'isRead',
                    'indexedAt',
                ],
                properties: {
                    uri: {
                        type: 'string',
                        format: 'at-uri',
                    },
                    cid: {
                        type: 'string',
                        format: 'cid',
                    },
                    author: {
                        type: 'ref',
                        ref: 'lex:app.bsky.actor.defs#profileView',
                    },
                    reason: {
                        type: 'string',
                        description: 'The reason why this notification was delivered - e.g. your post was liked, or you received a new follower.',
                        knownValues: [
                            'like',
                            'repost',
                            'follow',
                            'mention',
                            'reply',
                            'quote',
                            'starterpack-joined',
                            'verified',
                            'unverified',
                            'like-via-repost',
                            'repost-via-repost',
                            'subscribed-post',
                            'contact-match',
                        ],
                    },
                    reasonSubject: {
                        type: 'string',
                        format: 'at-uri',
                    },
                    record: {
                        type: 'unknown',
                    },
                    starterPack: {
                        description: 'The starter pack associated with this notification. Present when the notification is for a follow originating from a starter pack.',
                        type: 'ref',
                        ref: 'lex:app.bsky.graph.defs#starterPackViewBasic',
                    },
                    isRead: {
                        type: 'boolean',
                    },
                    indexedAt: {
                        type: 'string',
                        format: 'datetime',
                    },
                    labels: {
                        type: 'array',
                        items: {
                            type: 'ref',
                            ref: 'lex:com.atproto.label.defs#label',
                        },
                    },
                },
            },
        },
    },
